import { NextRequest, NextResponse } from "next/server";
import fs from "fs";
import path from "path";

const ORDERS_CSV = path.join(process.cwd(), "public", "data", "orders.csv");
const CSV_HEADER =
  "orderId,name,streetAddress,city,state,zipcode,totalAmount,timestamp,itemsJson\n";

function append(row: string) {
  if (!fs.existsSync(ORDERS_CSV)) fs.writeFileSync(ORDERS_CSV, CSV_HEADER);
  fs.appendFileSync(ORDERS_CSV, row);
}

export async function POST(req: NextRequest) {
  const body = await req.json();
  const {
    name,
    streetAddress,
    city,
    state,
    zipcode,
    items,
    totalAmount,
    timestamp,
  } = body;

  // Generate a plausible e-commerce order id: e.g. "ORD-20240610-ABCD"
  function generateOrderId() {
    const date = new Date();
    const y = date.getFullYear().toString().slice(-2);
    const m = String(date.getMonth() + 1).padStart(2, "0");
    const d = String(date.getDate()).padStart(2, "0");
    const letters = Array.from({ length: 4 }, () =>
      String.fromCharCode(65 + Math.floor(Math.random() * 26))
    ).join("");
    return `${letters}-${y}${m}${d}`;
  }
  const orderId = generateOrderId();
  const arrivalDate = new Date(Date.now() + 3 * 86_400_000)
    .toISOString()
    .split("T")[0];

  /* very-naïve CSV escaping */
  const safe = (v: string | number) =>
    String(v).replace(/"/g, '""').replace(/,/g, " ");

  append(
    [
      orderId,
      safe(name),
      safe(streetAddress),
      safe(city),
      safe(state),
      safe(zipcode),
      totalAmount,
      timestamp,
      `"${safe(JSON.stringify(items))}"`,
    ].join(",") + "\n"
  );

  return NextResponse.json({
    orderId,
    status: "success",
    message: "Order placed successfully",
    arrivalDate,
    orderDetails: {
      name,
      streetAddress,
      city,
      state,
      zipcode,
      totalAmount,
      timestamp,
      items,
    },
  });
}

import { parse } from "csv-parse/sync";
import { promises as fs } from "fs";
import path from "path";

export async function GET(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  // Validate
  const { id: idRaw } = await params;
  const id = Number(idRaw);
  if (Number.isNaN(id)) {
    return new Response(
      JSON.stringify({ error: "Invalid style id – must be a number" }),
      { status: 400, headers: { "Content-Type": "application/json" } }
    );
  }

  // Read & parse the CSV
  const csvPath = path.join(process.cwd(), "public", "data", "styles.csv");
  const csvRaw = await fs.readFile(csvPath, "utf8");
  const records: Record<string, string>[] = parse(csvRaw, {
    columns: true,
    skip_empty_lines: true,
  });

  // Look‑up
  const style = records.find((r) => Number(r.id) === id);
  if (!style) {
    return new Response(
      JSON.stringify({ error: `Style with id ${id} not found` }),
      { status: 404, headers: { "Content-Type": "application/json" } }
    );
  }

  // Success
  return new Response(JSON.stringify({ style }), {
    status: 200,
    headers: { "Content-Type": "application/json" },
  });
}

import fs from "fs";
import path from "path";
import { parse } from "csv-parse/sync";

/**
 * A single record coming from styles.csv
 * (keep the fields aligned with the CSV header):
 */
export interface StyleItem {
  id: number;
  gender: string;
  masterCategory: string;
  subCategory: string;
  articleType: string;
  baseColour: string;
  season: string;
  year: number;
  usage: string;
  productDisplayName: string;
  imageURL: string;
  priceUSD: number;
}

/** Internal in-memory cache (populated on first access) */
let cache: StyleItem[] | null = null;

/**
 * Parse _public/data/styles.csv_ on first call and
 * keep the result in memory for the lifetime of the process.
 */
export function getStylesCache(): StyleItem[] {
  if (cache) return cache;

  const csvPath = path.join(process.cwd(), "public", "data", "styles.csv");
  const raw = fs.readFileSync(csvPath, "utf-8");

  const records: Record<string, string>[] = parse(raw, {
    columns: true,
    skip_empty_lines: true,
    trim: true,
  });

  cache = records.map((r) => ({
    id: Number(r.id),
    gender: r.gender,
    masterCategory: r.masterCategory,
    subCategory: r.subCategory,
    articleType: r.articleType,
    baseColour: r.baseColour,
    season: r.season,
    year: Number(r.year),
    usage: r.usage,
    productDisplayName: r.productDisplayName,
    imageURL: r.imageURL,
    priceUSD: Number(r.priceUSD),
  }));

  return cache;
}

